def parse_duration(value: str) -> int:
    """Convert strings like '1h30m' into seconds."""
    total = 0
    number = ""
    for char in value:
        if char.isdigit():
            number += char
        elif char == "h":
            total += int(number) * 3600
            number = ""
        elif char == "m":
            total += int(number) * 60
            number = ""
    return total

