import unittest
from pagination import paginate

class PaginateTests(unittest.TestCase):
    def test_first_page(self):
        self.assertEqual(paginate(list(range(10)), 1, 3)["items"], [0, 1, 2])
    def test_last_partial_page(self):
        result = paginate(list(range(10)), 4, 3)
        self.assertEqual(result["items"], [9])
        self.assertEqual(result["total_pages"], 4)
    def test_page_out_of_range_is_empty(self):
        self.assertEqual(paginate(list(range(10)), 9, 3)["items"], [])
    def test_rejects_page_zero(self):
        with self.assertRaises(ValueError):
            paginate([1], 0, 3)
